def run_partition(sink, partition, attempt, keyed):
    record = {"partition": partition, "event": "fit-report-ready"}
    if keyed:
        sink.setdefault(f"app-0004/partition-{partition}", record)
    else:
        sink.setdefault("log", []).append(dict(record, attempt=attempt))
    if attempt == 0 and partition == 0:
        raise ConnectionError("executor lost after the side effect")


for keyed in (False, True):
    sink = {}
    for partition in range(8):
        for attempt in range(2):
            try:
                run_partition(sink, partition, attempt, keyed)
                break
            except ConnectionError:
                continue
    size = len(sink) if keyed else len(sink["log"])
    print(f"keyed={keyed}: {size} sink records for 8 partitions")

import math

MIN_OVERHEAD_MIB = 384
NON_JVM_FACTOR = 0.40


def pod_memory(heap_mib):
    return heap_mib + max(MIN_OVERHEAD_MIB, math.floor(heap_mib * NON_JVM_FACTOR))


driver, executor = pod_memory(1024), pod_memory(512)
quota = {"pods": 8, "requests.cpu": 4, "requests.memory": 6 * 1024}
used = {"pods": 3, "requests.cpu": 1 + 2 * 1, "requests.memory": driver + 2 * executor}
print("driver pod", driver, "MiB; executor pod", executor, "MiB")
for key in quota:
    print(f"{key:16} {used[key]:>6} of {quota[key]}")
headroom = {
    "pods": quota["pods"] - 1,
    "requests.cpu": quota["requests.cpu"] - 1,
    "requests.memory": (quota["requests.memory"] - driver) // executor,
}
print("max executors per limit:", headroom, "-> binding:", min(headroom, key=headroom.get))

def verdict(slice_json):
    ready = [
        e["targetRef"]["name"]
        for e in slice_json["endpoints"]
        if e["conditions"].get("ready") and e.get("targetRef", {}).get("kind") == "Pod"
    ]
    if len(ready) == 1:
        return f"accept: single driver endpoint {ready[0]}"
    if not ready:
        return "reject: Service has no ready endpoint (wrong label or pod not ready)"
    return f"reject: selector matches {len(ready)} pods {ready}"


def endpoint(name, ready=True):
    return {"conditions": {"ready": ready}, "targetRef": {"kind": "Pod", "name": name}}


